method.description:
Called every frame while the screen fades in ([param fade] rises from [code]0.0[/code] to [code]1.0[/code] over [member fade_in_duration]) and fades out (back to [code]0.0[/code] over [member fade_out_duration]). Override it to animate the screen yourself (slide in, shader dissolve); the default fade of the layer is not applied then.
[codeblocks]
[gdscript]
func _update_fade(fade):
    $Curtain.position.y = lerpf(-get_viewport().get_visible_rect().size.y, 0.0, fade)
[/gdscript]
[csharp]
public override void _UpdateFade(float fade)
{
    var curtain = GetNode<Control>("Curtain");
    curtain.Position = new Vector2(curtain.Position.X, Mathf.Lerp(-GetViewport().GetVisibleRect().Size.Y, 0.0f, fade));
}
[/csharp]
[/codeblocks]
